// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }
    function testFuzz_property(uint256 depositAmount, uint8 iterations) public {
        depositAmount = bound(depositAmount, 1, 1 ether);
        iterations = uint8(bound(iterations, 1, 10));

        address actor = makeAddr("actor");
        uint256 totalDeposited = 0;
        uint256 totalWithdrawn = 0;

        for (uint256 i = 0; i < iterations; i++) {
            vm.deal(actor, depositAmount);
            vm.prank(actor);
            c.deposit{value: depositAmount}();
            totalDeposited += depositAmount;

            uint256 balanceBefore = address(c).balance;
            vm.prank(actor);
            c.withdrawAll();
            uint256 withdrawn = balanceBefore - address(c).balance;
            totalWithdrawn += withdrawn;
        }

        assertTrue(totalWithdrawn <= totalDeposited);
    }
}
